"""Chapter 3 examples, version 3.0.0 - the nineteen code examples of the chapter 3 deck 3.0.0 (new file; examples_v1_x are the earlier decks' and stay as they are).
Each example is a listing of single-line statements, the last one an expression whose repr the deck prints under the listing; `show` lists the expressions whose values the
result picture of the slide is drawn from (the first is the printed one). The listings run after the PRELUDE, one fresh namespace each, and call the chapter library
sen0401_ch03_core_lib_v1_0_0 as T. Nothing here records an answer: examples_run_v3_0_0.py runs every listing and writes examples_out_v3_0_0.json; the deck is drawn from that file.
`rec` is the data the example reads from a saved file (shown on the slide as 'Recorded ...'), or None when everything is computed on the spot."""
__version__ = "3.0.0"
PRELUDE = "import base64\nimport datetime\nimport hashlib\nimport json\nimport sen0401_ch03_core_lib_v1_0_0 as T\n"
LIB = "sen0401_ch03_core_lib_v1_0_0"

P1, P2, P3, P4, P5, P6, P7 = ("From Bitcoin to Bitcoin Core", "Bitcoin Development Environment", "Running a Bitcoin Core Node", "Bitcoin Core API",
                              "Exploring and Decoding Transactions", "Exploring Blocks", "Alternative Clients, Libraries, and Toolkits")

G = lambda lines, note: {"lines": lines, "note": note}
EXAMPLES = [
 {"id": "ex01", "name": "A version number that carries a vote", "branch": P1, "picture": "table", "rec": None,
  "groups": [G(["v = 0x20000002"], "The version field of a block header that signals support for a new rule."),
             G(["top = v >> 29", "bits = [b for b in range(29) if v >> b & 1]", "(hex(v), top, bits)"], "The top three bits mark a version-bits block (BIP 9); each lower bit that is set is one proposal's vote.")],
  "show": ["(hex(v), top, bits)", "bin(v)[2:].zfill(32)"]},
 {"id": "ex02", "name": "Release tags sort by number, not by letters", "branch": P2, "picture": "table", "rec": "git tags listed on 2026-10-04",
  "groups": [G(["final = [t for t in T.TAGS if 'rc' not in t]"], "Release candidates carry rc in their tag; the final releases do not."),
             G(["text = sorted(final)", "num = sorted(final, key=T.version_key)", "(text[0], num[0])"], "Sorted as text, v0.10.0 comes before v0.9.5; sorted by number, the oldest comes first.")],
  "show": ["(text[0], num[0])", "text[:4]", "num[:4]"]},
 {"id": "ex03", "name": "What a release folder holds", "branch": P2, "picture": "table", "rec": "file list of release 31.1",
  "groups": [G(["bins = T.LAYOUT['bin']", "libs = T.LAYOUT['libexec']"], "A release unpacks into a bin folder of programs and a libexec folder of parts they use."),
             G(["(len(bins), len(libs), 'bitcoind' in bins)"], "Seven programs, among them the node bitcoind and its client bitcoin-cli.")],
  "show": ["(len(bins), len(libs), 'bitcoind' in bins)", "[(b, T.ROLE[b]) for b in bins]", "libs"]},
 {"id": "ex04", "name": "A download must match its published hash", "branch": P2, "picture": "diagram", "rec": "SHA256SUMS of release 31.1",
  "groups": [G(["listed = T.SUMS['bitcoin-31.1-x86_64-linux-gnu.tar.gz']"], "The release's SHA256SUMS file lists the expected hash of every archive."),
             G(["computed = T.RECOMPUTED", "(listed == computed, listed[:12])"], "Hash the downloaded archive yourself; equal texts mean it is the file that was published.")],
  "show": ["(listed == computed, listed[:12])", "len(listed)", "computed[:12]"]},
 {"id": "ex05", "name": "The command line wins over the file", "branch": P3, "picture": "table", "rec": None,
  "groups": [G(["conf = T.parse_conf(T.CONF_TEXT)", "cli = {'dbcache': '2048'}"], "The file sets the cache to 450 and turns the index on; the command line asks for 2048."),
             G(["used = {**conf, **cli}", "used"], "Merge the file first and the command line last, so the command line wins where both speak.")],
  "show": ["used", "conf", "cli"]},
 {"id": "ex06", "name": "How the database cache is shared out", "branch": P3, "picture": "native chart", "rec": None,
  "groups": [G(["total = 1024", "parts = T.cache_split(total)"], "The node is given 1024 MiB of cache; the library divides it the way Bitcoin Core does."),
             G(["(parts, sum(parts))"], "A little goes to two small databases; nearly everything serves the coins cache.")],
  "show": ["(parts, sum(parts))", "parts"]},
 {"id": "ex07", "name": "Pruning and the transaction index do not mix", "branch": P3, "picture": "table", "rec": "refusal printed by release 31.1",
  "groups": [G(["a, b = {'prune': 550}, {'txindex': 1}", "c = {'prune': 550, 'txindex': 1}"], "Three option sets: prune alone, index alone, and both together."),
             G(["[T.check_options(o)[0] for o in (a, b, c)]"], "The index needs every block on disk, so a pruned node cannot also keep it.")],
  "show": ["[T.check_options(o)[0] for o in (a, b, c)]", "[T.check_options(o)[1] for o in (a, b, c)]", "[a, b, c]"]},
 {"id": "ex08", "name": "An alert text is cleaned before it runs", "branch": P3, "picture": "table", "rec": None,
  "groups": [G(["msg = \"x'; reboot; '\""], "A hostile alert text tries to close the quote and run a second command."),
             G(["cmd = 'notify.sh \"Alert: %s\"'", "(T.clean(msg), len(msg) - len(T.clean(msg)))"], "The node strips every character outside a short safe list, so both quotes vanish.")],
  "show": ["(T.clean(msg), len(msg) - len(T.clean(msg)))", "T.alert_command(cmd, msg)", "msg"]},
 {"id": "ex09", "name": "One JSON-RPC call and its reply", "branch": P4, "picture": "diagram", "rec": "the book's sample reply",
  "groups": [G(["body = T.rpc_body('getblockchaininfo')"], "A call is a small JSON text that names the method and its parameters."),
             G(["reply = json.loads(T.REPLY)", "r = reply['result']", "(json.loads(body)['method'], r['blocks'], reply['error'])"], "The node answers with a result, an error that is empty, and the id of the call.")],
  "show": ["(json.loads(body)['method'], r['blocks'], reply['error'])", "reply['id']", "sorted(reply)"]},
 {"id": "ex10", "name": "The cookie is a fresh password", "branch": P4, "picture": "table", "rec": "the book's example cookie",
  "groups": [G(["cookie = '__cookie__:' + T.COOKIE"], "bitcoind writes a new random secret into the .cookie file every time it starts."),
             G(["token = base64.b64encode(cookie.encode()).decode()", "raw = bytes.fromhex(T.COOKIE)", "(len(T.COOKIE), len(raw), token[:12])"], "The client sends user and secret in a header, Base64-encoded; the secret is 32 bytes.")],
  "show": ["(len(T.COOKIE), len(raw), token[:12])", "cookie[:11]", "'Basic ' + token[:12]"]},
 {"id": "ex11", "name": "rpcauth stores a salted hash, not the password", "branch": P4, "picture": "table", "rec": None,
  "groups": [G(["salt = T.SALT", "line = T.rpcauth('alice', 'correct horse', salt)"], "A static credential keeps the user, a salt and a keyed hash instead of the password."),
             G(["[len(x) for x in line.replace('$', ':').split(':')]"], "The three parts have 5, 32 and 64 characters.")],
  "show": ["[len(x) for x in line.replace('$', ':').split(':')]", "line.split('$')", "line == T.rpcauth('alice', 'wrong', salt)"]},
 {"id": "ex12", "name": "Reading getblockchaininfo", "branch": P4, "picture": "table", "rec": "getblockchaininfo of release 31.1",
  "groups": [G(["i = json.loads(T.GETBLOCKCHAININFO)"], "bitcoin-cli getblockchaininfo answers in JSON; this is the answer of an offline node of release 31.1."),
             G(["(i['chain'], i['blocks'], i['initialblockdownload'])"], "A fresh node knows only the first block and says that it is still downloading.")],
  "show": ["(i['chain'], i['blocks'], i['initialblockdownload'])", "i['bestblockhash']", "int(i['chainwork'], 16)", "i['difficulty']", "i['verificationprogress']"]},
 {"id": "ex13", "name": "Decoding Alice's transaction", "branch": P5, "picture": "native chart", "rec": "decoderawtransaction of release 31.1",
  "groups": [G(["tx = json.loads(T.ALICE_DECODED)", "sat = lambda v: round(v * 10**8)"], "decoderawtransaction shows Alice's payment as JSON; the amounts are written in bitcoin."),
             G(["outs = [(o['n'], sat(o['value'])) for o in tx['vout']]", "outs"], "In satoshis, 20,000 return to Alice and 75,000 pay the store.")],
  "show": ["outs", "[o['scriptPubKey']['type'] for o in tx['vout']]", "tx['vsize']"]},
 {"id": "ex14", "name": "The txid leaves the witness out", "branch": P5, "picture": "table", "rec": "decoderawtransaction of release 31.1",
  "groups": [G(["raw = bytes.fromhex(T.ALICE_HEX)", "txid, wtxid = T.txid(raw), T.wtxid(raw)"], "Hash the transaction without its witness for the txid, and with it for the second hash."),
             G(["(txid[:16], wtxid[:16])"], "The two differ because the signature sits in the witness; the txid ignores it, so a changed signature cannot change the txid.")],
  "show": ["(txid[:16], wtxid[:16])", "txid == json.loads(T.ALICE_DECODED)['txid']", "wtxid == json.loads(T.ALICE_DECODED)['hash']"]},
 {"id": "ex15", "name": "Weight units and virtual bytes", "branch": P5, "picture": "native chart", "rec": "decoderawtransaction of release 31.1",
  "groups": [G(["raw = bytes.fromhex(T.ALICE_HEX)", "base, wit = T.split_witness(raw)"], "Split the transaction into the part every node counts in full and the witness part."),
             G(["weight = 4 * len(base) + len(wit)", "(weight, -(-weight // 4))"], "Base bytes weigh four units, witness bytes one; a virtual byte is four units, rounded up.")],
  "show": ["(weight, -(-weight // 4))", "(len(raw), len(base), len(wit))", "json.loads(T.ALICE_DECODED)['weight']"]},
 {"id": "ex16", "name": "A block's name is the hash of its header", "branch": P6, "picture": "table", "rec": "block 123,456 saved from a public API",
  "groups": [G(["b = T.BLOCK_123456", "h = T.header(b)"], "Block 123,456 as saved from a public API; its header packs into 80 bytes."),
             G(["name = T.hash256(h)[::-1].hex()", "(len(h), name == b['id'], name[:24])"], "Hash the header twice and reverse the bytes: the block's own name, with its zeros in front.")],
  "show": ["(len(h), name == b['id'], name[:24])", "T.header_fields(b)", "name"]},
 {"id": "ex17", "name": "Rebuilding the merkle root", "branch": P6, "picture": "native chart", "rec": "block 123,456 saved from a public API",
  "groups": [G(["ids = T.TXIDS_123456"], "The 13 transactions of block 123,456, as their ids."),
             G(["root, sizes = T.merkle(ids)", "(root[:16], sizes)"], "Hash neighbours in pairs, level after level, until one hash is left: the merkle root.")],
  "show": ["(root[:16], sizes)", "root == T.BLOCK_123456['merkle_root']", "root"]},
 {"id": "ex18", "name": "Median time of the last eleven blocks", "branch": P6, "picture": "native chart", "rec": "block times saved from a public API",
  "groups": [G(["t = T.BLOCK_TIMES", "window = [t[h] for h in range(123446, 123457)]"], "The timestamps of the eleven blocks that end with block 123,456."),
             G(["median = sorted(window)[5]", "(median, median == T.BLOCK_123456['mediantime'])"], "The sixth of eleven sorted times is the median time; the saved block says the same.")],
  "show": ["(median, median == T.BLOCK_123456['mediantime'])", "[(x - window[0]) // 60 for x in window]"]},
 {"id": "ex19", "name": "How fresh are the alternative toolkits", "branch": P7, "picture": "native chart", "rec": "package registries queried on 2026-10-02",
  "groups": [G(["days = T.age_days(T.QUERIED)"], "Nine toolkits, each with the date of its latest release; count the days back from the query."),
             G(["(days['python-bitcoinlib'], days['bitcoinjs-lib'])"], "python-bitcoinlib last released 1,217 days before the query; bitcoinjs-lib only 25.")],
  "show": ["(days['python-bitcoinlib'], days['bitcoinjs-lib'])", "sorted(days.items(), key=lambda kv: kv[1])"]},
]
for _e in EXAMPLES:
    _e["lines"] = [l for g in _e["groups"] for l in g["lines"]]
